class Solution:
    def minFallingPathSum(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        if m == 1 and n == 1:
            return grid[0][0]
        min_arr = [0 for _ in range(n)]
        for i in range(m):
            prefix = [float('inf') for _ in range(n)]
            suffix = [float('inf') for _ in range(n)]
            current_row = [elem1+elem2 for elem1, elem2 in zip(grid[i], min_arr)]
            for i in range(1, n):
                prefix[i] = min(prefix[i-1], current_row[i-1])
            for i in range(n-2, -1, -1):
                suffix[i] = min(suffix[i+1], current_row[i+1])
            min_arr = [min(pre, suff) for pre, suff in zip(prefix, suffix)]
        return min(min_arr)

class Solution:
    def minInsertions(self, s: str) -> int:
        n = len(s)
        prev_prev = [0]*n
        prev = [0]*n
        curr = [0] * n

        for l in range(1, n):
            for i in range(l, n):
                if s[i] == s[i-l]:
                    curr[i] = prev_prev[i-1]
                else:
                    curr[i] = min(prev[i-1], prev[i])+1
            # print(curr)
            prev_prev, prev, curr = prev, curr, prev_prev

        return prev[-1]

from functools import cache
class Solution:
    def minimumDistance(self, word: str) -> int:
        alphabets = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        COL = 6
        index = { c:(i//COL, i%COL) for i, c in enumerate(alphabets)}
        def dist(a, b):
            return abs(index[a][0] - index[b][0]) + abs(index[a][1] - index[b][1])
        @cache
        def dfs(lhand, rhand, i):
            if i == len(word): return 0
            res = float('inf')
            res = min(res, dfs(word[i], rhand, i+1)) if lhand == -1 else min(res, dist(lhand, word[i])+dfs(word[i], rhand, i+1))
            res = min(res, dfs(lhand, word[i],i+1)) if rhand == -1 else min(res, dist(word[i], rhand) + dfs(lhand, word[i], i+1))
            return res
        return dfs(-1, -1, 0)

