class Solution(object):
    def stoneGameIII(self, stoneValue):
        n = len(stoneValue)
        suffixSum = [0 for _ in range(n+1)]
        dp = [0 for _ in range(n+1)]
        for i in range(n-1, -1, -1):
            suffixSum[i] = suffixSum[i+1] + stoneValue[i]
        for i in range(n-1, -1, -1):
            dp[i] = stoneValue[i] + suffixSum[i+1] - dp[i+1]
            for k in range(i+1, min(n, i+3)):
                dp[i] = max(dp[i], suffixSum[i] - dp[k+1])
        if dp[0]*2 == suffixSum[0]:
            return "Tie"
        elif dp[0]*2 > suffixSum[0]:
            return "Alice"
        else:
            return "Bob"

class Solution:
    def numOfWays(self, n: int) -> int:
        two_c_options = 6
        tot_options = 12
        for i in range(n-1):
            temp = tot_options
            tot_options = (two_c_options * 5) + ((tot_options - two_c_options) * 4)
            two_c_options = (two_c_options * 3) + ((temp - two_c_options) * 2)
            tot_options = tot_options % (1000000007)
        return tot_options
